# -*- coding: utf-8 -*-
from . import unittest, mock, patch
from taf.selenium.mobile.gnb.oam.coam.classical.pages.software import SoftwareManagementPage


class TestSoftware(unittest.TestCase):

    def setUp(self):
        self._tool = mock.Mock()
        self._page = SoftwareManagementPage(self._tool)

    @patch("taf.selenium.mobile.gnb.oam.coam.classical.pages.software.RollbackSoftwareModal")
    def test_software_rollback(self, mock_Modal):
        modal = mock.Mock()
        mock_Modal.return_value = modal
        modal.wait_until_rollback_software_modal_appear = mock.Mock()
        modal.confirm = mock.Mock()
        self._tool.click_enabled_element_after_visible = mock.Mock()
        self._page.software_rollback()
        modal.wait_until_rollback_software_modal_appear.assert_called()
        modal.confirm.assert_called()
        self._tool.click_enabled_element_after_visible.assert_called()

    def test_check_current_software_version(self):
        expect_res = 'ver'
        self._tool.get_dict_from_elements_by_xpath = mock.Mock(return_value=expect_res)
        output = self._page.check_current_software_version(key=None)
        self._tool.get_dict_from_elements_by_xpath.assert_called()
        self.assertEqual(expect_res, output)
